#!/usr/bin/env python3
"""Generate rtl/carrier_lut.svh from the model's LUT so RTL and model can't drift."""
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "model"))
from bdmodel.correlator import COS_LUT, LUT_BITS, SIN_LUT  # noqa: E402


def render() -> str:
    lines = [
        "// Generated by tools/gen_carrier_lut.py -- do not edit.",
        f"// {1 << LUT_BITS}-entry carrier LUT, amplitude round(15*cos/sin(2*pi*(k+0.5)/{1 << LUT_BITS})).",
        "function automatic signed [4:0] carr_cos(input [4:0] k);",
        "  case (k)",
    ]
    lines += [f"    5'd{k}: carr_cos = {int(v)};" for k, v in enumerate(COS_LUT)]
    lines += ["    default: carr_cos = 0;", "  endcase", "endfunction", "",
              "function automatic signed [4:0] carr_sin(input [4:0] k);", "  case (k)"]
    lines += [f"    5'd{k}: carr_sin = {int(v)};" for k, v in enumerate(SIN_LUT)]
    lines += ["    default: carr_sin = 0;", "  endcase", "endfunction", ""]
    return "\n".join(lines)


if __name__ == "__main__":
    out = ROOT / "rtl" / "carrier_lut.svh"
    text = render()
    if "--check" in sys.argv:
        sys.exit(0 if out.read_text() == text else "rtl/carrier_lut.svh is stale")
    out.write_text(text)
